/* Portfolio interactions and recruiter-friendly context; vanilla JS for GitHub Pages. */
(() => {
  'use strict';

  const email = 'lucascoster90@gmail.com';
  const year = document.querySelector('#current-year');
  if (year) year.textContent = new Date().getFullYear();
  document.documentElement.classList.remove('no-js');

  const navLabels = {
    about: 'About · Profile',
    experience: '2nd Period · Experience',
    education: '1st Period · Education',
    projects: '3rd Period · Projects',
    consulting: 'Consulting · Services',
    skills: 'Skills · Roster',
    contact: 'Overtime · Contact'
  };
  document.querySelectorAll('header a[href^="#"]').forEach(link => {
    const id = link.getAttribute('href').slice(1);
    if (navLabels[id]) link.textContent = navLabels[id];
  });

  const style = document.createElement('style');
  style.textContent = `
    .recruiter-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
    .recruiter-actions a,.recruiter-actions button{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:8px 14px;border:1px solid rgba(255,255,255,.2);border-radius:6px;background:#111827;color:#F8FAFC;text-decoration:none;font:600 12px Arial,sans-serif;cursor:pointer}
    .recruiter-actions a:hover,.recruiter-actions button:hover{border-color:#38BDF8;color:#38BDF8}
    .recruiter-actions .email-primary{background:#38BDF8;border-color:#38BDF8;color:#0B0F17}
    .case-study{margin-top:14px;padding:14px;border:1px solid rgba(255,255,255,.12);border-radius:8px;background:rgba(17,24,39,.7);color:#e2e8f0}
    .case-study summary{cursor:pointer;color:#38BDF8;font-weight:600}
    .case-study dl{display:grid;grid-template-columns:1fr;gap:10px;margin:12px 0 0}
    .case-study dt{margin-bottom:3px;color:#F8FAFC;font-size:12px;font-weight:700}
    .case-study dd{margin:0;color:#cbd5e1;font-size:13px;line-height:1.6}
    .skill-context{margin:16px 0;padding:16px;border:1px solid rgba(255,255,255,.12);border-radius:8px;background:#111827;color:#e2e8f0}
    .skill-context h3{margin:0 0 10px;color:#F8FAFC}
    .skill-context-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px}
    .skill-context-group{padding:10px;border:1px solid rgba(255,255,255,.08);border-radius:6px}
    .skill-context-group h4{margin:0 0 6px;color:#38BDF8;font-size:12px}
    .skill-context-group p{margin:0;color:#cbd5e1;font-size:12px;line-height:1.6}
    .toast-feedback{position:fixed;right:16px;bottom:16px;z-index:1000;padding:10px 14px;border-radius:6px;background:#111827;color:#F8FAFC;border:1px solid rgba(255,255,255,.15);opacity:0;transform:translateY(6px);transition:opacity .2s,transform .2s;pointer-events:none}
    .toast-feedback.visible{opacity:1;transform:translateY(0)}
    @media(max-width:600px){.recruiter-actions{gap:8px}.recruiter-actions a,.recruiter-actions button{flex:1}.case-study{padding:12px}}
  `;
  document.head.append(style);

  // Keep the mobile menu and its links available on touch screens.
  const header = document.querySelector('header');
  const openMenu = document.querySelector('#mobile-menu-open');
  const closeMenu = document.querySelector('#mobile-menu-close');
  openMenu?.addEventListener('click', () => { header?.classList.add('active'); document.body.classList.add('active'); });
  closeMenu?.addEventListener('click', () => { header?.classList.remove('active'); document.body.classList.remove('active'); });
  document.querySelectorAll('header a[href^="#"]').forEach(link => link.addEventListener('click', event => {
    const target = document.querySelector(link.getAttribute('href'));
    if (!target) return;
    event.preventDefault();
    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    header?.classList.remove('active'); document.body.classList.remove('active');
  }));
  document.querySelector('#to-top')?.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
  document.querySelector('#lead-down span')?.addEventListener('click', () => document.querySelector('#about')?.scrollIntoView({ behavior: 'smooth' }));

  // Make email reachable immediately; copy is an optional shortcut, not a gate.
  const hero = document.querySelector('#lead-content');
  if (hero && !hero.querySelector('.recruiter-actions')) {
    const actions = document.createElement('div');
    actions.className = 'recruiter-actions';
    const emailLink = document.createElement('a');
    emailLink.className = 'email-primary'; emailLink.href = `mailto:${email}`; emailLink.textContent = 'Email Lucas';
    const copyButton = document.createElement('button'); copyButton.type = 'button'; copyButton.textContent = 'Copy email';
    actions.append(emailLink, copyButton); hero.append(actions);
    const toast = document.createElement('div'); toast.className = 'toast-feedback'; toast.setAttribute('role', 'status'); toast.setAttribute('aria-live', 'polite'); document.body.append(toast);
    let toastTimer;
    copyButton.addEventListener('click', async () => {
      try { await navigator.clipboard.writeText(email); }
      catch (error) {
        const field = document.createElement('textarea'); field.value = email; field.setAttribute('readonly', ''); field.style.position = 'fixed'; field.style.opacity = '0'; document.body.append(field); field.select(); document.execCommand('copy'); field.remove();
      }
      toast.textContent = 'Email copied'; toast.classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('visible'), 1800);
    });
  }

  // Retain original experience timeline presentation without a jQuery dependency.
  const timeline = document.querySelector('#experience-timeline');
  if (timeline) [...timeline.children].forEach(entry => {
    if (entry.parentElement.classList.contains('vtimeline-block')) return;
    const date = entry.dataset.date;
    const point = document.createElement('div'); point.className = 'vtimeline-point';
    const block = document.createElement('div'); block.className = 'vtimeline-block';
    const icon = document.createElement('div'); icon.className = 'vtimeline-icon'; icon.setAttribute('aria-hidden', 'true'); icon.textContent = '•';
    entry.classList.add('vtimeline-content');
    if (date) { const dateLabel = document.createElement('span'); dateLabel.className = 'vtimeline-date'; dateLabel.textContent = date; point.append(dateLabel); }
    point.append(icon); block.append(entry); point.append(block); timeline.append(point);
  });

  // Project summaries distinguish the problem, approach and evidenced result.
  const caseStudies = [
    { match: 'Ovarian Cancer Early Warning Application', problem: 'Support early detection research for ovarian cancer using a National Cancer Institute dataset.', approach: 'A team-built Python application using PyTorch and TensorFlow libraries, with a Streamlit frontend.', result: 'A full working machine-learning application is available as a live demo. The original project description does not provide a measured clinical or model-accuracy result.', link: 'https://ovapredict.streamlit.app/', linkText: 'Open live application' },
    { match: '3D Hand Tracking', problem: 'Estimate a hand’s 3D shape and pose from a single monocular RGB input.', approach: 'A custom TensorFlow model developed through the QMIND AI team; intended extensions included two-hand and hand-to-object interactions.', result: 'Presented at the CUCAI conference. No quantitative evaluation was stated in the original portfolio description.', link: 'https://github.com/lucas22c/3D-Hand-Tracking', linkText: 'View GitHub project' },
    { match: '32-Bit Verilog Computer', problem: 'Build a functional 32-bit CPU that supports arithmetic, function calls, jumps, and memory operations.', approach: 'A Verilog CPU connected to an ALU, RAM, and bus; simulations tested the described operations.', result: 'The described CPU and simulation tests were completed. No benchmark or quantitative result was stated. The source repository is private, so the public project blueprint is linked instead.', link: 'ELEC_490-498_Blueprint.pdf', linkText: 'View project blueprint (PDF)' },
    { match: 'Pet Nose Estimation', problem: 'Predict a pet’s nose location from an image while addressing image sizing and training-data preparation.', approach: 'A computer-vision model based on ResNet18, built as part of a deep-learning course project.', result: 'The model predicts nose location in pet images. The original description does not state a quantitative accuracy result.', link: 'https://github.com/lucas22c/ELEC475_Lab5', linkText: 'View GitHub project' },
    { match: 'Running VS Jumping Prediction', problem: 'Classify whether a user’s movement is running or jumping.', approach: 'A group used iPhone-collected movement data, pre-processed it, then ran it through a pre-built model.', result: 'A movement-classification project was built from the collected data. No quantitative model result was stated.', link: 'https://github.com/lucas22c/ELEC390Project', linkText: 'View GitHub project' },
    { match: 'Phishing Email Detection', problem: 'Identify dangerous URLs in a Kaggle dataset.', approach: 'Pre-processed the dataset and used an LSTM model; changed the model and data to target accuracy and training time.', result: 'The project explored accuracy improvements and reduced training time, but the original description provides no measured values. The final report is available.', link: 'Final_Report.pdf', linkText: 'Read final report (PDF)' }
  ];
  const projectCards = [...document.querySelectorAll('#projects .project')];
  caseStudies.forEach(study => {
    const card = projectCards.find(item => item.querySelector('h3')?.textContent.trim() === study.match);
    if (!card || card.querySelector('.case-study')) return;
    const projectInfo = card.querySelector('.project-info'); if (!projectInfo) return;
    const oldLink = projectInfo.querySelector('a[href]');
    if (oldLink) { oldLink.href = study.link; oldLink.textContent = study.linkText; oldLink.target = '_blank'; oldLink.rel = 'noopener noreferrer'; }
    const details = document.createElement('details'); details.className = 'case-study';
    const summary = document.createElement('summary'); summary.textContent = 'Problem · Approach · Result';
    const list = document.createElement('dl');
    [['Problem', study.problem], ['Architecture and approach', study.approach], ['Result', study.result]].forEach(([label, text]) => {
      const wrapper = document.createElement('div'); const term = document.createElement('dt'); const description = document.createElement('dd');
      term.textContent = label; description.textContent = text; wrapper.append(term, description); list.append(wrapper);
    });
    details.append(summary, list); projectInfo.append(details);
  });

  // Explain where selected technologies were used; no self-assigned skill ratings.
  const skills = document.querySelector('#skills');
  if (skills && !skills.querySelector('.skill-context')) {
    const context = document.createElement('section'); context.className = 'skill-context';
    const title = document.createElement('h3'); title.textContent = 'Skills in context';
    const grid = document.createElement('div'); grid.className = 'skill-context-grid';
    const groups = [
      ['Frontend and application work', 'TypeScript and HTML — Briza full-stack API platform. React, JavaScript, and HTML are included in my skills roster; project use is not specified in the portfolio.'],
      ['Machine learning and computer vision', 'Python and TensorFlow — QMIND and 3D Hand Tracking. Python also appears in the ovarian-cancer, pet-nose, and movement-classification projects.'],
      ['Systems, data, and delivery', 'SQL and Docker — Briza platform storage and testing. GitHub and Agile — Briza team practices. Verilog — 32-Bit Verilog Computer. AWS is listed among my skills; a specific project or role is not identified in the portfolio.']
    ];
    groups.forEach(([heading, copy]) => { const item = document.createElement('article'); item.className = 'skill-context-group'; const h = document.createElement('h4'); const p = document.createElement('p'); h.textContent = heading; p.textContent = copy; item.append(h, p); grid.append(item); });
    context.append(title, grid); skills.append(context);
  }

  // Preserve the template's expand-more behavior and smooth scroll.
  document.querySelector('#view-more-projects')?.addEventListener('click', event => {
    event.preventDefault(); const more = document.querySelector('#more-projects');
    if (more) { more.style.display = 'flex'; more.hidden = false; event.currentTarget.hidden = true; }
  });
})();
